content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-17-queue-010

=== 用户原始指令 (query.txt) ===
帮我搞一个，前面等的人数要变，点进去能取消预约，能看天气，要有红色提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我搞一个，前面等的人数要变，点进去能取消预约，能看天气，要有红色提醒",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "queue-booking-20260709-001"
        }
      }
    }
  ],
  "dataModelSchema": {
    "queue": {
      "locationName": {
        "type": "string",
        "description": "排队业务或门店名称",
        "sampleValue": "门诊取号"
      },
      "aheadCount": {
        "type": "number",
        "description": "当前前方等待人数",
        "sampleValue": 8
      },
      "waitLabel": {
        "type": "string",
        "description": "等待人数的短标签",
        "sampleValue": "前方等待"
      },
      "estimateText": {
        "type": "string",
        "description": "预计等待时长展示文本",
        "sampleValue": "约12分钟"
      },
      "windowName": {
        "type": "string",
        "description": "当前预约对应的窗口或队列位置",
        "sampleValue": "3号窗口"
      },
      "updatedText": {
        "type": "string",
        "description": "叫号信息更新时间短文本",
        "sampleValue": "09:30更新"
      },
      "alertText": {
        "type": "string",
        "description": "红色提醒短文本",
        "sampleValue": "留意叫号"
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询地区名称",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          }
        }
      },
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "预约日程实体 ID，用于进入详情页取消预约",
              "sampleValue": "queue-booking-20260709-001"
            },
            "dtStart": {
              "type": "string",
              "description": "预约开始或预计叫号时间",
              "sampleValue": "09:45"
            },
            "title": {
              "type": "string",
              "description": "预约日程标题",
              "sampleValue": "排队预约"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标，适合用于多云天气和排队等待时的天气提示。"
    }
  ]
}

